messages.content:
Tool response:
Tool: update_listing_shipping
Description: Update Listing Shipping
Parameters:
    {
      "type": "object",
      "properties": {
        "listing_id": {
          "type": "integer",
          "title": "Listing Id",
          "description": ""
        },
        "handling_time_days": {
          "type": "integer",
          "title": "Handling Time Days"
        },
        "shipping_options": {
          "items": {
            "properties": {
              "shipping_type": {
                "type": "string",
                "title": "Shipping Type"
              },
              "carrier_name": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Carrier Name"
              },
              "service_name": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Service Name"
              },
              "cost": {
                "type": "number",
                "title": "Cost"
              }
            },
            "type": "object",
            "required": [
              "shipping_type",
              "cost"
            ],
            "title": "ShippingOptionRequest"
          },
          "type": "array",
          "title": "Shipping Options"
        }
      },
      "required": [
        "listing_id",
        "handling_time_days",
        "shipping_options"
      ]
    }
